        const missing=[];tables.forEach((table,index)=>{const source=pivot.sources[index];for(const field of [...pivot.rows,...pivot.columns,...pivot.values.map(item=>item.field),...pivot.filters.map(item=>item.field)].filter(field=>![P.SOURCE,P.RECORD].includes(field)))if(!table.headers.includes(source.mapping?.[field]||field))missing.push(field);});if(missing.length)throw new Error(t('缺少字段：','Missing fields: ')+[...new Set(missing)].join('、'));
